<div class="general-settings-actions"><?php if($sepaState['can_write']&&!$draft['pending']):?><button class="btn btn-solid theme-primary" name="sepa_intent" value="preview"><?=e($snt('Ganze Lastschriftentscheidung unverbindlich prüfen'))?></button><?php endif;if(!$draft['pending']):?><button class="btn btn-outline theme-secondary" name="sepa_intent" value="discard"><?=e($snt('Eigenen ungespeicherten Lastschriftentwurf verwerfen'))?></button><?php endif;if($sepaState['can_write']&&($draft['pending']||$draft['conflicted'])):?><button class="btn btn-outline theme-secondary" name="sepa_intent" value="current"><?=e($snt('Ganze Lastschriftangaben mit aktuellem Stand erneut prüfen'))?></button><?php endif ?></div>
<?php if($review&&!$draft['pending']):?><section class="card" data-sepa-review><h2><?=e($snt('Geprüfte, noch nicht ausgeführte Lastschriftentscheidung'))?></h2><p><?=e($snt($snOperations[$review['input']['operation']]))?></p><?php $sepaShownSource=$review['source']['preview']['source']??$review['source']['snapshot']['source'];require __DIR__.'/sepa-source-native.php';?>
<?php if(isset($review['source']['return']['financial'])):$fundingReview=$review['source']['return']['financial']['review'];$fundingEntry=$fundingReview['selected'][0]['entry'];$returnedAmount=array_sum(array_column($fundingReview['selected'],'amount_cents'));?><section class="notice" data-sepa-return-financial-review><h3><?=e($snt('Geprüfter Rechnungsstand nach Rücklastschrift'))?></h3><p><?=e($fundingEntry['display_number'].' · '.$snt('Danach bezahlt').': '.euro((int)$fundingEntry['allocated_cents']-$returnedAmount).' · '.$snt('Danach offen').': '.euro((int)$fundingEntry['remaining_cents']+$returnedAmount))?></p><p><?=e($snt('Lastschriftstatus und Finanzzuordnung werden gemeinsam gespeichert. Ursprüngliche Zahlungen, Belege und Bankdatei bleiben erhalten. Die Finanzzuordnung kann danach nicht getrennt vom dokumentierten Lastschriftvorgang zurückgenommen werden.'))?></p></section><?php endif?>
<?php if(isset($review['source']['return']['document'])):$proof=$review['source']['return']['document'];?><p><?=e($snt('Tatsächlich ausgewählter Rücklastschriftnachweis'))?>: <?=e($proof['document']['title'].' · '.$proof['file']['name'])?></p><a class="btn btn-outline theme-secondary" href="<?=e(url(['view'=>'documents','doc'=>$proof['document']['id']]))?>"><?=e($snt('Ausgewähltes ursprüngliches Dokument öffnen'))?></a><?php endif ?>
<?php if(isset($review['source']['correction'])):$correction=$review['source']['correction']['review'];$isUndo=$correction['kind']==='undo';$delta=$correction['funding']!==null?array_sum(array_column($correction['funding']['selected'],'amount_cents')):0;$paid=(int)$correction['entry']['allocated_cents'];if($isUndo){if($correction['restored_ranges']!==null)$paid=\Kulturhus\Verein\PaymentFundingRanges::cents($correction['restored_ranges'],(int)$correction['entry']['amount_cents']);if($correction['legacy']!==null)$paid=(int)$correction['entry']['amount_cents'];}else $paid-=$delta;?><section class="notice" data-sepa-correction-review><h3><?=e($snt('Gemeinsam geprüfte Rücklastschriftänderung'))?></h3><p><?=e($correction['entry']['display_number'].' · '.$snt('Danach bezahlt').': '.euro($paid).' · '.$snt('Danach offen').': '.euro((int)$correction['entry']['amount_cents']-$paid))?></p><p><?=e($snt('Die Änderung speichert ausschließlich die Zuordnung. Tatsächliche Umsätze, ursprüngliche Rechnungen und Bankdateien bleiben erhalten. Eine Rücknahme sendet keinen neuen Bankauftrag.'))?></p><section data-sepa-correction-source><h4><?=e($snt('Dokumentierter Rücklastschriftgrund'))?></h4><pre><?=e($correction['effect']['record']['reason'])?></pre><p><?=e(dateDe($correction['counter']['booked_on']).' · '.$correction['counter']['counterparty'].' · '.euro((int)$correction['counter']['cents']))?></p><pre><?=e($correction['counter']['description'])?></pre>
<?php if(isset($correction['documents']['return_document'])):$proof=$correction['documents']['return_document'];?><a class="btn btn-outline theme-secondary" href="<?=e(url(['view'=>'documents','doc'=>$proof['document']['id']]))?>"><?=e($snt('Ursprünglichen Rücklastschriftnachweis öffnen').': '.$proof['document']['title'])?></a><?php endif?>
<?php foreach($correction['financials']as$financial):?><a class="btn btn-outline theme-secondary" href="<?=e(url(array_replace(bankTransactionContext($correction['counter']['id'],$_GET),['partial_return_original'=>$financial['id']])))?>"><?=e($snt('Vorhandenen Finanznachweis öffnen'))?> <span><?=e($financial['id'])?></span></a><?php endforeach?></section>
<a class="btn btn-outline theme-secondary" href="<?=e(url(bankTransactionContext($correction['counter']['id'],$_GET)))?>"><?=e($snt('Tatsächliche Rückzahlung und Finanznachweis öffnen'))?></a></section><?php endif?>
<?php foreach($review['source']['entries']as$source):?><p><?=e($source['entry']['display_number'])?> · <?=e($snt('Aktuell offener Beitrag'))?>: <?=e(euro($source['entry']['remaining_cents']))?></p><?php if($source['invoice']):?><a class="btn btn-outline theme-secondary" href="<?=e(url(['view'=>'documents','doc'=>$source['invoice']['file']['document_id']]))?>"><?=e($snt('Tatsächliches ursprüngliches Rechnungsdokument öffnen'))?></a><?php endif;endforeach ?>
<?=hidden('sepa_key',$draft['key'])?><?php if($sepaState['can_write']):?><label class="general-settings-check"><input class="check" type="checkbox" name="sepa_approved" value="1"><span><?=e($snt('Genau dieser Auftrag, diese Aktion, die Forderungen, Mandate und ganzen Angaben einschließlich des tatsächlichen Vorabinformations- oder Banknachweises sind geprüft.'))?></span></label><button class="btn btn-solid theme-primary" name="sepa_intent" value="accept"><?=e($snt('Geprüfte Lastschriftentscheidung bewusst speichern'))?></button><?php endif ?></section><?php endif ?></form></section><?php endif ?>
